def get_google_icon(name: str, color: str = "#FFFFFF", size: int = 24) -> QIcon:
    """Returns a QIcon for given Google Material Symbol name and color."""
    path_data = GOOGLE_MATERIAL_SVGS.get(name, GOOGLE_MATERIAL_SVGS["settings"])
    svg_str = f"""<svg xmlns="http://www.w3.org/2000/svg" height="{size}" viewBox="0 -960 960 960" width="{size}">
        <path fill="{color}" d="{path_data.split('d="')[1].split('"')[0]}"/>
    </svg>"""
    
    renderer = QSvgRenderer(QByteArray(svg_str.encode("utf-8")))
    pixmap = QPixmap(size, size)
    pixmap.fill(QColor(0, 0, 0, 0))
    painter = QPainter(pixmap)
    renderer.render(painter)
    painter.end()
    return QIcon(pixmap)

def get_google_pixmap(name: str, color: str = "#FFFFFF", size: int = 24) -> QPixmap:
    path_data = GOOGLE_MATERIAL_SVGS.get(name, GOOGLE_MATERIAL_SVGS["settings"])
    svg_str = f"""<svg xmlns="http://www.w3.org/2000/svg" height="{size}" viewBox="0 -960 960 960" width="{size}">
        <path fill="{color}" d="{path_data.split('d="')[1].split('"')[0]}"/>
    </svg>"""
    renderer = QSvgRenderer(QByteArray(svg_str.encode("utf-8")))
    pixmap = QPixmap(size, size)
    pixmap.fill(QColor(0, 0, 0, 0))
    painter = QPainter(pixmap)
    renderer.render(painter)
    painter.end()
    return pixmap
